
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_edmggah_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_edmggah", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.621962886826253e+00, -2.630133611403193e+00, -2.633926821816211e+00, -2.635276538694583e+00, -2.621697702123378e+00, -2.550097345799718e+00, -2.374439817654109e+00, -2.093357581756051e+00, -1.742034933996617e+00, -1.370450857596845e+00, -9.994394542740795e-01, -6.206045181017864e-01, -4.807211677458991e-01, -4.157815384807880e-01, -3.226903444162793e-01, -2.272525060380279e-01, -1.481415943780657e-01, -9.037575016538667e-02, -5.596045079127512e-02, -3.710227945158550e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


